theorem extension_gradient_norm {n : ℕ} {hn : 2 ≤ n}
    {source : DFP.InverseIteration (Fin 2)} {target : DFP.InverseIteration (Fin n)}
    (h : IdentityInitialization.DimensionExtensionData n hn source target) (k : ℕ) :
    ‖DFP.gradients target.objective target.point k‖ =
      ‖DFP.gradients source.objective source.point k‖ := by
  rw [extension_gradients h, (OrthogonalExtension.planeEmbedding n hn).norm_map]

theorem canonicalSecant_eq_source {p : Parameters} {κ c₁ c₂ : ℝ}
    {w : DFP.StrongWolfeCounterexample (Fin 2) (1 / 2) (3 / 2) c₁ c₂}
    (h : PlanarCounterexample.SourceIdentity p κ w) (k : ℕ) :
    DFP.gradientChanges (DFP.gradients w.iteration.objective w.iteration.point) k =
      secant p k := by
  rw [h.gradients, DFP.gradientChanges_apply, secant_def]

theorem bound {R : Θ → ℝ → E} {s : Set Θ} {q η₀ : ℝ} {ω : ℝ → ℝ}
    (hω : IsUniformRemainderModulusOn R s q η₀ ω) {θ : Θ} {η ε : ℝ}
    (hθ : θ ∈ s) (hη : η ∈ Set.Ioc 0 η₀) (hε : 0 < |ε|) (hεη : |ε| ≤ η) :
    ‖R θ ε‖ ≤ ω η * |ε| ^ q := by
  -- Project the pointwise estimate from the defining specification.
  exact hω.2.2.2 θ hθ η hη ε hε hεη

theorem boundedCoeff {m : ℕ} {f : Θ → E → F}
    {J : Θ → FiniteTaylorJet ℝ E F m} {a : E} {K : Set Θ}
    (hJ : FiniteTaylorJet.IsUniformOn f J a K) (n : Fin (m + 1)) :
    ∃ B ≥ 0, ∀ θ ∈ K, ‖(J θ).coeff n‖ ≤ B := by
  -- Project the degreewise boundedness clause of uniformity.
  exact hJ.1 n

theorem remainder {m : ℕ} {f : Θ → E → F}
    {J : Θ → FiniteTaylorJet ℝ E F m} {a : E} {K : Set Θ}
    (hJ : FiniteTaylorJet.IsUniformOn f J a K) (C : ℝ) (hC : 0 < C) :
    IsUniformRemainderOn f J a K C (m : ℝ) := by
  -- Specialize the every-positive-coefficient remainder clause.
  exact hJ.2 C hC

lemma compactFiberEventually {X : Type u} {Y : Type v}
    [TopologicalSpace X] [TopologicalSpace Y] {x : X} {K : Set Y}
    (hK : IsCompact K) {P : X → Y → Prop}
    (hP : ∀ y ∈ K, ∀ᶠ z : X × Y in 𝓝 (x, y), P z.1 z.2) :
    ∀ᶠ x' in 𝓝 x, ∀ y ∈ K, P x' y := by
  -- Compactness turns the pointwise product neighborhoods into one first-factor neighborhood.
  exact hK.eventually_forall_of_forall_eventually hP

theorem gradient_objective {ι : Type u} {κ : Type v}
    [Fintype ι] [Fintype κ] {f : EuclideanSpace ℝ ι → ℝ}
    {p : EuclideanSpace ℝ (ι ⊕ κ)} (hf : DifferentiableAt ℝ f (left p)) :
    gradient (objective (κ := κ) f) p =
      (EuclideanSpace.sumEquivProd (𝕜 := ℝ)).symm (gradient f (left p), right p) := by
  exact (hasGradientAt_objective (κ := κ) hf.hasGradientAt).gradient

theorem HasHessianBounds.toObjectiveSublevel {n : ℕ} {m M : ℝ}
    {iteration : InverseIteration (Fin n)}
    (h : HasHessianBounds m M iteration.objective) :
    HasHessianBoundsOnObjectiveSublevel m M iteration := by
  intro z hz
  exact HasHessianBounds.at h z

theorem hasGradientAt_objective_embed {ι : Type u} {κ : Type v}
    [Fintype ι] [Fintype κ] {f : EuclideanSpace ℝ ι → ℝ}
    {z g : EuclideanSpace ℝ ι} (hf : HasGradientAt f g z) :
    HasGradientAt (objective f) (embed g : EuclideanSpace ℝ (ι ⊕ κ))
      (embed z : EuclideanSpace ℝ (ι ⊕ κ)) := by
  exact EuclideanSpace.OrthogonalSum.Gradient.hasGradientAt_objective_inl (κ := κ) hf

theorem gradient_objective_embed {ι : Type u} {κ : Type v}
    [Fintype ι] [Fintype κ] {f : EuclideanSpace ℝ ι → ℝ}
    {z : EuclideanSpace ℝ ι} (hf : DifferentiableAt ℝ f z) :
    gradient (objective f : EuclideanSpace ℝ (ι ⊕ κ) → ℝ) (embed z) =
      embed (gradient f z) := by
  exact EuclideanSpace.OrthogonalSum.Gradient.gradient_objective_inl (κ := κ) hf

theorem hasHessianBounds_objective {ι : Type u} {κ : Type v}
    [Fintype ι] [Fintype κ] {m M : ℝ} {f : EuclideanSpace ℝ ι → ℝ}
    (hf : ContDiff ℝ 2 f) (h : HasHessianBounds m M f) (hm : m ≤ 1) (hM : 1 ≤ M) :
    HasHessianBounds m M (objective (κ := κ) f) := by
  rw [objective_eq]
  exact EuclideanSpace.OrthogonalSum.Gradient.hasHessianBounds_objective hf h hm hM

theorem gradient_perturbation_center {c : ℕ → E} {ρ : ℕ → ℝ} {a : ℕ → E}
    (h : Geometry c ρ a) (k : ℕ) : gradient (perturbation c ρ a) (c k) = a k := by
  exact (hasGradientAt_perturbation_center h k).gradient

theorem objective_center {c : ℕ → E} {ρ : ℕ → ℝ} {a : ℕ → E}
    (h : Geometry c ρ a) (k : ℕ) : objective c ρ a (c k) = (1 / 2 : ℝ) * ‖c k‖ ^ 2 := by
  rw [objective_apply, perturbation_center h k, add_zero]

theorem gradient_objective_center {c : ℕ → E} {ρ : ℕ → ℝ} {a : ℕ → E}
    (h : Geometry c ρ a) (k : ℕ) : gradient (objective c ρ a) (c k) = c k + a k := by
  exact (hasGradientAt_objective_center h k).gradient

theorem FinExtensionIdentity.gradient_norm {n : ℕ} {hn : 2 ≤ n} {c₁ c₂ : ℝ}
    {c : DFP.StrongWolfeCounterexample (Fin 2) (1 / 2) (3 / 2) c₁ c₂}
    {w : DFP.StrongWolfeCounterexample (Fin n) (1 / 2) (3 / 2) c₁ c₂}
    (h : FinExtensionIdentity n hn c w) (k : ℕ) :
    ‖DFP.gradients w.iteration.objective w.iteration.point k‖ =
      ‖DFP.gradients c.iteration.objective c.iteration.point k‖ := by
  rw [h.gradients, (planeEmbedding n hn).norm_map]

theorem FinExtensionIdentity.source_objective {n : ℕ} {hn : 2 ≤ n} {p : Parameters}
    {κ c₁ c₂ : ℝ} {c : DFP.StrongWolfeCounterexample (Fin 2) (1 / 2) (3 / 2) c₁ c₂}
    {w : DFP.StrongWolfeCounterexample (Fin n) (1 / 2) (3 / 2) c₁ c₂}
    (h : FinExtensionIdentity n hn c w) (hsource : PlanarCounterexample.SourceIdentity p κ c) :
    w.iteration.objective = EuclideanSpace.OrthogonalSum.Gradient.objective
      (κ := Fin (n - 2)) (InterpolationSum.polarObjective p κ) ∘ coordinateEquiv n hn := by
  rw [h.objective, hsource.objective]

theorem FinExtensionIdentity.source_point {n : ℕ} {hn : 2 ≤ n} {p : Parameters}
    {κ c₁ c₂ : ℝ} {c : DFP.StrongWolfeCounterexample (Fin 2) (1 / 2) (3 / 2) c₁ c₂}
    {w : DFP.StrongWolfeCounterexample (Fin n) (1 / 2) (3 / 2) c₁ c₂}
    (h : FinExtensionIdentity n hn c w) (hsource : PlanarCounterexample.SourceIdentity p κ c)
    (k : ℕ) : w.iteration.point k = planeEmbedding n hn (p.point k) := by
  rw [h.point, hsource.point]

theorem FinExtensionIdentity.source_stepLength {n : ℕ} {hn : 2 ≤ n} {p : Parameters}
    {κ c₁ c₂ : ℝ} {c : DFP.StrongWolfeCounterexample (Fin 2) (1 / 2) (3 / 2) c₁ c₂}
    {w : DFP.StrongWolfeCounterexample (Fin n) (1 / 2) (3 / 2) c₁ c₂}
    (h : FinExtensionIdentity n hn c w) (hsource : PlanarCounterexample.SourceIdentity p κ c) :
    w.iteration.stepLength = PhysicalRealization.prescribedStepLength p := by
  rw [h.stepLength, hsource.stepLength]

theorem FinExtensionIdentity.source_inverseHessian {n : ℕ} {hn : 2 ≤ n} {p : Parameters}
    {κ c₁ c₂ : ℝ} {c : DFP.StrongWolfeCounterexample (Fin 2) (1 / 2) (3 / 2) c₁ c₂}
    {w : DFP.StrongWolfeCounterexample (Fin n) (1 / 2) (3 / 2) c₁ c₂}
    (h : FinExtensionIdentity n hn c w) (hsource : PlanarCounterexample.SourceIdentity p κ c)
    (k : ℕ) : w.iteration.inverseHessian k = extendedMatrix n hn (p.inverseHessian k) := by
  rw [h.inverseHessian, hsource.inverseHessian]

theorem FinExtensionIdentity.source_gradients {n : ℕ} {hn : 2 ≤ n} {p : Parameters}
    {κ c₁ c₂ : ℝ} {c : DFP.StrongWolfeCounterexample (Fin 2) (1 / 2) (3 / 2) c₁ c₂}
    {w : DFP.StrongWolfeCounterexample (Fin n) (1 / 2) (3 / 2) c₁ c₂}
    (h : FinExtensionIdentity n hn c w) (hsource : PlanarCounterexample.SourceIdentity p κ c)
    (k : ℕ) : DFP.gradients w.iteration.objective w.iteration.point k =
      planeEmbedding n hn (p.gradient k) := by
  rw [h.gradients, hsource.gradients]

theorem CounterexampleProperties.gradientNorm_tendsto_one {ε c₁ c₂ : ℝ}
    {w : DFP.StrongWolfeCounterexample (Fin 2) (1 / 2) (3 / 2) c₁ c₂}
    (h : CounterexampleProperties ε w) :
    Tendsto (fun k ↦ ‖DFP.gradients w.iteration.objective w.iteration.point k‖)
      atTop (𝓝 1) := by
  simpa only [h.gradientLimit] using w.gradientNormTendsto

