    {n : ℕ}
    {H : ℕ → EuclideanSpace ℝ (Fin n) →L[ℝ] EuclideanSpace ℝ (Fin n)}
    (hH : H 0 = 1) :
    canonicalMatrixSequence H 0 = (1 : Matrix (Fin n) (Fin n) ℝ) := by
  rw [canonicalMatrixSequence_apply, hH, map_one]
